import torch


def wush_transforms(X, W, eps=1e-5):
    """示意：分别用两个因子的二阶统计做白化，成对施加以保持乘积不变。"""
    def whiten(S):
        d, V = torch.linalg.eigh(S + eps * torch.eye(S.shape[0], device=S.device))
        return V @ torch.diag(d.rsqrt()) @ V.t()

    Sx = X.t() @ X / max(X.shape[0] - 1, 1)      # [d_in, d_in]
    Sw = W @ W.t() / max(W.shape[1] - 1, 1)      # [d_out, d_out]
    Tx, Tw = whiten(Sx), whiten(Sw)
    # X @ W == (Tx @ X) @ (Tw.inverse() @ W)  -> 成对量化后再还原
    return Tx, torch.linalg.inv(Tw)

import torch
import torch.nn as nn

class MeanFlowNet(nn.Module):
    """预测平均速度场 u(x_t, t)，输出与输入同形状。"""
    def __init__(self, dim=64, hidden=128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(dim + 1, hidden), nn.SiLU(),
            nn.Linear(hidden, hidden), nn.SiLU(),
            nn.Linear(hidden, dim),
        )

    def forward(self, x_t, t):                 # x_t: [B, D], t: [B] in [0, 1]
        return self.net(torch.cat([x_t, t[:, None]], dim=-1))

def mean_flow_loss(model, x0, x1):
    """回归 u(x_t, t) -> x_1 - x_0 的蒙特卡洛估计。"""
    t = torch.rand(x0.size(0), device=x0.device)
    x_t = (1 - t)[:, None] * x0 + t[:, None] * x1
    target = x1 - x0
    return ((model(x_t, t) - target) ** 2).mean()

@torch.no_grad()
def one_step_sample(model, x0):
    """一步采样：x_1 ~= x_0 + u(x_0, 0)。"""
    t0 = torch.zeros(x0.size(0), device=x0.device)
    return x0 + model(x0, t0)

if __name__ == "__main__":
    dim, B = 64, 8
    model = MeanFlowNet(dim)
    x0, x1 = torch.randn(B, dim), torch.randn(B, dim)
    loss = mean_flow_loss(model, x0, x1)
    out = one_step_sample(model, x0)
    print(loss.item(), out.shape)

from typing import Any


def evaluate(results: list[dict[str, Any]]) -> dict[str, float]:
    """results: 每条任务的三项验收结果（摘要口径：完成/准确/是否需人工介入）。"""
    n = len(results)
    if n == 0:
        return {"SR": float("nan"), "HIR": float("nan")}
    sr = sum(1 for r in results if r["completed"] and r["accurate"]) / n
    hir = sum(1 for r in results if r["human_intervention"]) / n
    return {"SR": sr, "HIR": hir}


