import torch
import torch.nn as nn


class IntraOptionPolicy(nn.Module):
    def __init__(self, state_dim, n_options, n_actions):
        super().__init__()
        self.n_options = n_options
        self.head = nn.Linear(state_dim, n_options * n_actions)
        self.n_actions = n_actions

    def forward(self, state):
        logits = self.head(state).view(-1, self.n_options, self.n_actions)
        return torch.distributions.Categorical(logits=logits)


def intra_option_loss(dist, option, action, option_value, mask=None):
    logits = dist.logits
    if mask is not None:
        # mask 为 0 的动作概率置零后重新归一化
        logits = logits.masked_fill(mask == 0, float('-inf'))
    dist = torch.distributions.Categorical(logits=logits)
    logp = dist.log_prob(action)
    return -(logp * option_value.detach()).mean()

import torch

def merge_task_vectors(base_sd, vectors, lambdas=None):
    # base_sd: 基座 state_dict; vectors: [{"state": sd, "name": str}, ...]
    lambdas = lambdas or [1.0 / len(vectors)] * len(vectors)
    out = {k: v.clone() for k, v in base_sd.items()}
    for w, vec in zip(lambdas, vectors):
        for k, v in vec["state"].items():
            if out[k].dtype.is_floating_point:
                out[k] = out[k] + w * (v - base_sd[k])   # base + sum lambda * tau
    return out


def tau_norm(merged_sd, base_sd):
    return sum(((merged_sd[k] - base_sd[k]) ** 2).sum().item()
               for k in base_sd if base_sd[k].dtype.is_floating_point) ** 0.5

import torch


def compression_ratio(img_hw, latent_hw):
    # DC-SAE @ 512x512: 512 / 16 = 32 倍空间压缩（每个空间维度各降 32 倍）
    assert img_hw[0] / latent_hw[0] == img_hw[1] / latent_hw[1], "各向同性下采样"
    return img_hw[0] / latent_hw[0]


def psnr(x, x_hat, max_val=1.0):
    # 29.79 dB 对应 MSE ≈ 10 ** (-2.979) ≈ 1.05e-3
    mse = torch.mean((x - x_hat) ** 2)
    return float(10.0 * torch.log10(torch.tensor(max_val ** 2) / mse.clamp(min=1e-12)))


assert abs(compression_ratio((512, 512), (16, 16)) - 32.0) < 1e-9

import numpy as np
from collections import deque

def temporal_distance(goal, grid, blocked):
    # grid: (H, W); blocked: set of obstacles -> BFS 得到每格到目标的步数
    H, W = grid.shape
    dist = np.full((H, W), np.inf)
    dist[goal] = 0.0
    q = deque([goal])
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and (nr, nc) not in blocked:
                if dist[nr, nc] > dist[r, c] + 1:
                    dist[nr, nc] = dist[r, c] + 1
                    q.append((nr, nc))
    return dist   # phi(s, g) = dist[s]; 确定性环境下即时间距离


def fourier_features(x, B):
    # 随机傅里叶位置编码: 状态的替代表示
    proj = x @ B                     # B: (d, m) ~ N(0, sigma^2)
    return np.concatenate([np.sin(proj), np.cos(proj)], axis=-1)

def evidence_budget(horizon_s, window_s=30.0, n_windows=10, evi_per_s=50.0):
    # E = K * w * b, 同时报告占空比预算
    k = min(int(n_windows), max(int(horizon_s // window_s), 1))
    evidence = k * window_s * evi_per_s
    return {"K": k, "evidence": evidence, "rho": k * window_s / horizon_s}


def inefficiency_yield(n_trace=17000, eta=0.23):
    # 摘要口径：约 1.7 万条轨迹，23% 定位到低效模式
    return round(n_trace * eta)


if __name__ == "__main__":
    print(evidence_budget(86400.0))
    print("ineff traces ~", inefficiency_yield())
